function Modal({ isOpen, onClose, onConfirm, title, children }) {
    const modalRef = useRef(null);
    const triggerRef = useRef(null);

    useEffect(() => {
        if (isOpen) {
            triggerRef.current = document.activeElement;
            const focusableElements = modalRef.current.querySelectorAll(
                'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
            );
            if (focusableElements.length > 0) {
                // Focus the cancel button (usually the first or last)
                // In our case, cancel is the first button in footer
                focusableElements[0].focus();
            }

            const handleKeyDown = (e) => {
                if (e.key === 'Escape') onClose();
                if (e.key === 'Tab') {
                    const firstElement = focusableElements[0];
                    const lastElement = focusableElements[focusableElements.length - 1];

                    if (e.shiftKey) {
                        if (document.activeElement === firstElement) {
                            lastElement.focus();
                            e.preventDefault();
                        }
                    } else {
                        if (document.activeElement === lastElement) {
                            firstElement.focus();
                            e.preventDefault();
                        }
                    }
                }
            };

            document.addEventListener('keydown', handleKeyDown);
            return () => document.removeEventListener('keydown', handleKeyDown);
        } else {
            if (triggerRef.current) {
                triggerRef.current.focus();
            }
        }
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div className="modal-overlay" onClick={onClose}>
            <div 
                className="modal-content" 
                ref={modalRef}
                onClick={(e) => e.stopPropagation()}
                role="dialog"
                aria-modal="true"
                aria-labelledby="modal-title"
            >
                <div className="modal-header">
                    <h2 id="modal-title">{title}</h2>
                </div>
                <div className="modal-body">
                    {children}
                </div>
                <div className="modal-footer">
                    <button className="btn-secondary" onClick={onClose}>Cancel</button>
                    <button className="btn-danger" onClick={onConfirm}>Delete Image</button>
                </div>
            </div>
        </div>
    );
}

function App() {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isDeleted, setIsDeleted] = useState(false);

    const handleDeleteClick = () => {
        setIsModalOpen(true);
    };

    const handleConfirmDelete = () => {
        setIsDeleted(true);
        setIsModalOpen(false);
        // In a real app, you'd call an API here
        console.log("Image deleted");
    };

    if (isDeleted) {
        return (
            <main className="preview-container">
                <h1>Image Deleted</h1>
                <p>The image has been removed from your library.</p>
                <button className="btn-secondary" onClick={() => setIsDeleted(false)}>Undo (Demo)</button>
            </main>
        );
    }

    return (
        <main className="preview-container">
            <h1>Image Preview</h1>
            <div className="image-wrapper">
                <img 
                    src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80" 
                    alt="Scenic mountain landscape with a lake reflecting the sky" 
                />
            </div>
            <div className="controls">
                <button className="trigger" onClick={handleDeleteClick}>
                    Delete Image
                </button>
            </div>

            <Modal 
                isOpen={isModalOpen} 
                onClose={() => setIsModalOpen(false)} 
                onConfirm={handleConfirmDelete}
                title="Confirm Deletion"
            >
                <p>Are you sure you want to delete this image? This action cannot be undone and it will be removed from your library permanently.</p>
            </Modal>
        </main>
    );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
